//| label: leaflet-map-container

// Setup Leaflet + CSS
L = {
  const L = await require("leaflet@1.9.4/dist/leaflet.js");
  if (!document.getElementById('leaflet-css-fix')) {
    const link = document.createElement('link');
    link.id = 'leaflet-css-fix';
    link.rel = 'stylesheet';
    link.href = 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';
    document.head.appendChild(link);
  }
  return L;
}

data = transpose(data_py)
geo = FileAttachment("../../data/geojson/switzerland.geojson").json()
statsMap = new Map(data.map(d => [d.id, d]))
mutable selectionLeaflet = null 

// The map
mapContainer = {

  // Create a container div for the Leaflet map
  const container = document.createElement("div");
  container.style.height = "500px";
  container.style.width = "100%";
  container.style.borderRadius = "8px";
  container.style.border = "1px solid #ddd";

  // The container is yielded to be used in the reset button's function
  yield container; 

  // Zoom 7.8 and fit to Switzerland
  const map = L.map(container, {zoomSnap: 0, zoomDelta: 1, wheelPxPerZoomLevel: 5}).setView([46.8, 8.2], 7.8);

  //L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
  //  attribution: '&copy; OSM & CARTO', subdomains: 'abcd', maxZoom: 19
  //}).addTo(map);

  // The Swiss-specific tiles from OSM Switzerland, with bounds to prevent panning outside the country  
  L.tileLayer('https://tile.osm.ch/switzerland/{z}/{x}/{y}.png', {
    maxZoom: 18,
    attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
    bounds: [[45, 5], [48, 11]]
  }) .addTo(map);

  // Add the GeoJSON layer with styling and interactivity
  const geoLayer = L.geoJSON(geo, 
  {
    style: function(feature) {
      const stat = statsMap.get(feature.properties.name);
      return {
        color: "#00000087", weight: 1,
        fillColor: stat ? "#999" : "#999", 
        fillOpacity: 0.3
      };
    },
    onEachFeature: function(feature, layer) {
      layer.bindTooltip(feature.properties.name, {sticky: true});
      layer.on('click', function(e) {
        mutable selectionLeaflet = feature;
        map.flyToBounds(e.target.getBounds(), {padding: [10, 10], duration: 1.0});
        geoLayer.resetStyle();
        e.target.setStyle({ weight: 2, color: '#000000', fillColor: "#ffffff00"});
        L.DomEvent.stopPropagation(e);
      });
    }
  }).addTo(map);

  // Function to reset the map view and styles
  container.resetMap = () => {
      mutable selectionLeaflet = null;
      geoLayer.resetStyle();
      map.flyTo([46.8, 8.2], 7.8, {duration: 1.0});
  };

  // Reset the map when clicking outside of any canton
  map.on('click', container.resetMap);
}
